// The whale-tail activity indicator. The sprite sheets in assets/whale/ (one
// still, three loops) are generated by tool/make_whale_sprites.py.

import 'dart:convert';
import 'dart:math' as math;
import 'dart:ui' as ui;

import 'package:flutter/scheduler.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';

const deepSeekBlue = Color(0xFF4D6BFE);

const deepSeekBlueDark = Color(0xFF7A98FB);

Color whaleColorFor(Brightness brightness) => brightness == Brightness.dark ? deepSeekBlueDark : deepSeekBlue;

class WhaleSheet {
  const WhaleSheet(this.image, this.frames, this.frameMs);
  final ui.Image image;
  final int frames;
  final int frameMs;

  Duration get loop => Duration(milliseconds: frames * frameMs);
}

class WhaleAtlas {
  const WhaleAtlas({required this.frameWidth, required this.frameHeight, required this.columns, required this.levels});

  final int frameWidth;
  final int frameHeight;
  final int columns;
  final Map<int, WhaleSheet> levels;

  double get aspect => frameWidth / frameHeight;

  WhaleSheet sheet(int level) => levels[level.clamp(1, 4)] ?? levels[1]!;

  Rect frameRect(int frame) {
    final row = frame ~/ columns;
    final col = frame % columns;
    return Rect.fromLTWH(
      (col * frameWidth).toDouble(),
      (row * frameHeight).toDouble(),
      frameWidth.toDouble(),
      frameHeight.toDouble(),
    );
  }
}

abstract final class WhaleSprites {
  static const manifest = 'assets/whale/whale.json';

  static const aspect = 120 / 96;

  static WhaleAtlas? _atlas;
  static Future<WhaleAtlas>? _loading;

  static WhaleAtlas? get cached => _atlas;

  static Future<WhaleAtlas> load([AssetBundle? bundle]) => _loading ??= () async {
    try {
      return _atlas = await _load(bundle ?? rootBundle);
    } catch (_) {
      _loading = null;
      rethrow;
    }
  }();

  static Future<WhaleAtlas> _load(AssetBundle bundle) async {
    final json = jsonDecode(await bundle.loadString(manifest)) as Map<String, Object?>;
    final levels = <int, WhaleSheet>{};
    for (final entry in (json['levels'] as List).cast<Map<String, Object?>>()) {
      final data = await bundle.load('assets/whale/${entry['image']}');
      final codec = await ui.instantiateImageCodec(data.buffer.asUint8List());
      final frame = await codec.getNextFrame();
      codec.dispose();
      levels[entry['level'] as int] = WhaleSheet(frame.image, entry['frames'] as int, entry['frameMs'] as int);
    }
    return WhaleAtlas(
      frameWidth: json['frameWidth'] as int,
      frameHeight: json['frameHeight'] as int,
      columns: json['columns'] as int,
      levels: levels,
    );
  }
}

///

/// |---|---|---|---|

///

///

class WhaleTail extends StatefulWidget {
  const WhaleTail({super.key, this.level = 1, required this.color, this.height = 20, this.still = false});

  final int level;
  final Color color;

  final double height;

  final bool still;

  @override
  State<WhaleTail> createState() => WhaleTailState();
}

class WhaleTailState extends State<WhaleTail> with SingleTickerProviderStateMixin {
  late final Ticker _ticker = createTicker(_onTick);
  final _repaint = ValueNotifier<int>(0);
  WhaleAtlas? _atlas = WhaleSprites.cached;
  bool _reduced = false;

  static const _blend = Duration(milliseconds: 320);

  static const _ease = 0.35;

  int _form = 2;
  int? _from;
  double _mix = 1;

  final _phase = <int, double>{};

  double _rate = 0;
  Duration _last = Duration.zero;

  static int formOf(int level) => level <= 2 ? 2 : level.clamp(2, 4);

  static double rateOf(int level) => switch (level) {
    <= 0 => 0.3,
    1 => 0.5,
    _ => 1.0,
  };

  @override
  void initState() {
    super.initState();
    _form = formOf(widget.level);
    _rate = rateOf(widget.level);
    if (_atlas == null) {
      WhaleSprites.load().then((atlas) {
        if (!mounted) return;
        setState(() => _atlas = atlas);
        _sync();
      }, onError: (Object _) {});
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _reduced = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    _sync();
  }

  @override
  void didUpdateWidget(WhaleTail oldWidget) {
    super.didUpdateWidget(oldWidget);
    final form = formOf(widget.level);
    if (form != _form) {
      // Mid-blend: the fading one goes, the shown one becomes the old one.
      _from = _form;
      _form = form;
      _mix = 0;
    }
    _sync();
  }

  @override
  void dispose() {
    _ticker.dispose();
    _repaint.dispose();
    super.dispose();
  }

  bool get _moving => !widget.still && !_reduced;

  @visibleForTesting
  int get shownForm => _moving ? _form : 1;

  @visibleForTesting
  double get rate => _rate;

  @visibleForTesting
  int get frame => (_phase[_form] ?? 0).floor();

  /// Ticks whenever it moves (and the sprites are in).
  void _sync() {
    final moving = _moving && _atlas != null;
    if (moving && !_ticker.isActive) {
      _last = Duration.zero;
      _ticker.start();
    } else if (!moving && _ticker.isActive) {
      _ticker.stop();
      _repaint.value++;
    }
  }

  void _onTick(Duration elapsed) {
    final atlas = _atlas;
    if (atlas == null) return;
    final dt = (elapsed - _last).inMicroseconds / 1e6;
    _last = elapsed;
    if (dt <= 0) return;
    final target = rateOf(widget.level);
    _rate += (target - _rate) * (1 - math.exp(-dt / _ease));
    for (final form in [_form, ?_from]) {
      final sheet = atlas.sheet(form);
      if (sheet.frameMs <= 0) continue;
      final step = dt * 1000 / sheet.frameMs * _rate;
      _phase[form] = ((_phase[form] ?? 0) + step) % sheet.frames;
    }
    if (_from != null) {
      _mix += dt * 1e6 / _blend.inMicroseconds;
      if (_mix >= 1) {
        _mix = 1;
        _phase.remove(_from);
        _from = null;
      }
    }
    _repaint.value++;
  }

  @override
  Widget build(BuildContext context) {
    final size = Size(widget.height * WhaleSprites.aspect, widget.height);
    final atlas = _atlas;
    return ExcludeSemantics(
      child: SizedBox.fromSize(
        size: size,
        child: atlas == null
            ? null
            : CustomPaint(
                painter: _WhalePainter(atlas: atlas, state: this, repaint: _repaint, color: widget.color),
              ),
      ),
    );
  }

  List<(int, double, double)> _layers() {
    if (!_moving) return const [(1, 0, 1)];
    return [
      if (_from case final from?) (from, _phase[from] ?? 0, 1 - _mix),
      (_form, _phase[_form] ?? 0, _from == null ? 1 : _mix),
    ];
  }
}

class _WhalePainter extends CustomPainter {
  _WhalePainter({required this.atlas, required this.state, required Listenable repaint, required this.color})
    : super(repaint: repaint);

  final WhaleAtlas atlas;
  final WhaleTailState state;
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    // Every layer (two neighbouring frames of each form) is added with its
    // weight; the weights sum to 1, so overlapping strokes keep full ink.
    final draws = <(ui.Image, Rect, double)>[];
    for (final (form, phase, weight) in state._layers()) {
      final sheet = atlas.sheet(form);
      if (sheet.frames <= 1) {
        draws.add((sheet.image, atlas.frameRect(0), weight));
        continue;
      }
      final a = phase.floor() % sheet.frames;
      final t = phase - phase.floor();
      draws.add((sheet.image, atlas.frameRect(a), weight * (1 - t)));
      if (t > 0) {
        final b = (a + 1) % sheet.frames;
        draws.add((sheet.image, atlas.frameRect(b), weight * t));
      }
    }
    final dst = Offset.zero & size;
    final single = draws.length == 1;
    if (!single) canvas.saveLayer(dst, Paint());
    for (final (i, (image, src, weight)) in draws.indexed) {
      if (weight <= 0) continue;
      canvas.drawImageRect(
        image,
        src,
        dst,
        Paint()
          ..filterQuality = FilterQuality.medium
          ..blendMode = i == 0 ? BlendMode.srcOver : BlendMode.plus
          ..colorFilter = ColorFilter.mode(color.withValues(alpha: color.a * weight), BlendMode.srcIn),
      );
    }
    if (!single) canvas.restore();
  }

  @override
  bool shouldRepaint(_WhalePainter old) => old.atlas != atlas || old.state != state || old.color != color;
}
